/**
 * Sends a page view to the configured analytics HTTP endpoint.
 * Set ANALYTICS_ENDPOINT to the event collection URL in each environment.
 */
export async function trackPageView(path: string): Promise<void> {
  const endpoint = process.env.ANALYTICS_ENDPOINT

  if (!endpoint) {
    // Keep local development observable when no analytics service is configured.
    console.info('[analytics] page_view', { path })
    return
  }

  try {
    const response = await fetch(endpoint, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ event: 'page_view', path }),
      cache: 'no-store',
    })

    if (!response.ok) {
      console.error(`[analytics] page_view failed with status ${response.status}`)
    }
  } catch (error) {
    console.error('[analytics] page_view request failed', error)
  }
}

